export const EU_WAVE_CORE_TRANSLATIONS: Record<string, Record<EuWaveLocale, string>> = Object.fromEntries(
  Object.entries(EU_WAVE_CORE_ROWS).map(([source, values]) => [source, Object.fromEntries(EU_WAVE_LOCALES.map((locale, index) => [locale, values[index]]))]),
) as Record<string, Record<EuWaveLocale, string>>;

export function translateEuWavePhrase(source: string, locale: EuWaveLocale): string {
  return EU_WAVE_CORE_TRANSLATIONS[source]?.[locale] || source;
}

export function translateEuWaveRecord<T extends Record<string, string>>(source: T, locale: EuWaveLocale): T {
  return Object.fromEntries(Object.entries(source).map(([key, value]) => [key, translateEuWavePhrase(value, locale)])) as T;
}

export function translateEuWaveData<T>(source: T, locale: EuWaveLocale): T {
  if (typeof source === "string") return translateEuWavePhrase(source, locale) as T;
  if (Array.isArray(source)) return source.map((item) => translateEuWaveData(item, locale)) as T;
  if (source && typeof source === "object") return Object.fromEntries(Object.entries(source).map(([key, value]) => [key, translateEuWaveData(value, locale)])) as T;
  return source;
}
